/// NestedLoopJoiner implements nested loop joins.
#[derive(Clone)]
pub struct NestedLoopJoiner {
    /// The left source.
    left: Peekable<Rows>,
    /// The right source.
    right: Rows,
    /// The original right iterator state.
    right_original: Rows,
    /// The number of columns in the right source.
    right_columns: usize,
    /// True if a right match has been seen for the current left row.
    right_matched: bool,
    /// The join predicate.
    predicate: Option<Expression>,
    /// If true, emit a row when there is no match in the right source.
    outer: bool,
}

impl NestedLoopJoiner {
    /// Creates a new nested loop joiner.
    pub fn new(
        left: Rows,
        right: Rows,
        right_columns: usize,
        predicate: Option<Expression>,
        outer: bool,
    ) -> Self {
        Self {
            left: left.peekable(),
            right,
            right_original: right.clone(),
            right_columns,
            right_matched: false,
            predicate,
            outer,
        }
    }

    // Returns the next joined row, if any.
    fn try_next(&mut self) -> Result<Option<Row>> {
        loop {
            if let Some(Ok(left_row)) = self.left.peek() {
                if let Some(Ok(right_row)) = self.right.peek() {
                    // Check if the predicate matches
                    let matches = if let Some(ref pred) = self.predicate {
                        let mut combined_row = left_row.clone();
                        combined_row.extend(right_row.iter().cloned());
                        pred.evaluate(Some(&combined_row))
                            .map(|v| v == Value::Boolean(true))
                            .unwrap_or(false)
                    } else {
                        true
                    };

                    if matches {
                        self.right_matched = true;
                        let mut result = left_row.clone();
                        result.extend(right_row.iter().cloned());
                        self.right.next();
                        return Ok(Some(result));
                    } else {
                        self.right.next();
                    }
                } else {
                    self.right.next();
                }
            } else {
                // Left exhausted, check if we need to emit unmatched left rows
                if self.outer && !self.right_matched {
                    let mut result = left_row.clone();
                    result.resize(self.left.columns() + self.right_columns, Value::Null);
                    self.left.next();
                    return Ok(Some(result));
                }
                // Reset right iterator and move to next left row
                self.right = self.right_original.clone();
                self.right_matched = false;
                self.left.next();
                if self.left.peek().is_none() {
                    return Ok(None);
                }
            }
        }
    }
}

impl Iterator for NestedLoopJoiner {
    type Item = Result<Row>;

    fn next(&mut self) -> Option<Self::Item> {
        self.try_next().transpose()
    }
}

/// HashJoiner implements hash joins.
#[derive(Clone)]
pub struct HashJoiner {
    /// The left source.
    left: Rows,
    /// The left column to join on.
    left_column: usize,
    /// The right hash map to join on.
    right: HashMap<Value, Vec<Row>>,
    /// The number of columns in the right source.
    right_columns: usize,
    /// If true, emit a row when there is no match in the right source.
    outer: bool,
    /// Any pending matches to emit.
    pending: Rows,
}

impl HashJoiner {
    /// Creates a new hash joiner.
    pub fn new(
        left: Rows,
        left_column: usize,
        mut right: Rows,
        right_column: usize,
        right_columns: usize,
        outer: bool,
    ) -> Result<Self> {
        // Build hash map from right side
        let mut right_map = HashMap::new();
        for row in right {
            let row = row?;
            let key = row[right_column].clone();
            right_map.entry(key).or_insert_with(Vec::new).push(row);
        }

        Ok(Self {
            left: left.peekable(),
            left_column,
            right: right_map,
            right_columns,
            outer,
            pending: Box::new(std::iter::empty()),
        })
    }

    // Returns the next joined row, if any.
    fn try_next(&mut self) -> Result<Option<Row>> {
        // First, emit any pending rows from the left side
        if let Some(Ok(row)) = self.pending.peek() {
            self.pending.next();
            return Ok(Some(row.clone()));
        }

        // Process left side
        if let Some(Ok(left_row)) = self.left.peek() {
            let key = left_row[self.left_column].clone();
            let left_len = left_row.len();

            if let Some(right_rows) = self.right.get(&key) {
                for right_row in right_rows {
                    let mut result = left_row.clone();
                    result.extend(right_row.iter().cloned());
                    self.left.next();
                    return Ok(Some(result));
                }
            } else if self.outer {
                // No match, emit left row with nulls for right side
                let mut result = left_row.clone();
                result.resize(left_len + self.right_columns, Value::Null);
                self.left.next();
                return Ok(Some(result));
            } else {
                self.left.next();
            }
        } else {
            // Left exhausted, emit unmatched right rows for outer join
            if self.outer {
                for (key, right_rows) in &self.right {
                    for right_row in right_rows {
                        let mut result = vec![Value::Null; self.left_column];
                        result.push(key.clone());
                        result.extend(right_row.iter().cloned());
                        self.pending = Box::new(std::iter::once(Ok(result)));
                        return self.try_next();
                    }
                }
            }
            return Ok(None);
        }

        self.try_next()
    }
}

impl Iterator for HashJoiner {
    type Item = Result<Row>;

    fn next(&mut self) -> Option<Self::Item> {
        self.try_next().transpose()
    }
}

